function ConfirmDeleteDialog({ open, onCancel, onConfirm, imageName }) {
  const cancelRef = useRef(null);

  useEffect(() => {
    if (!open) return;
    const onKey = (e) => { if (e.key === "Escape") onCancel(); };
    document.addEventListener("keydown", onKey);
    cancelRef.current?.focus();
    document.body.style.overflow = "hidden";
    return () => {
      document.removeEventListener("keydown", onKey);
      document.body.style.overflow = "";
    };
  }, [open, onCancel]);

  if (!open) return null;

  return (
    <div
      className="modal-overlay"
      role="dialog"
      aria-modal="true"
      aria-labelledby="delete-title"
      onMouseDown={(e) => { if (e.target === e.currentTarget) onCancel(); }}
    >
      <div className="modal">
        <div className="modal-header">
          <div className="modal-icon" aria-hidden="true">
            <Icon name="alert" />
          </div>
          <div className="modal-body">
            <h2 id="delete-title">Delete this image?</h2>
            <p>
              "{imageName}" will be permanently removed from your library. This action cannot be undone.
            </p>
          </div>
        </div>
        <div className="modal-footer">
          <button ref={cancelRef} className="btn btn-ghost" onClick={onCancel}>Cancel</button>
          <button className="btn btn-danger" onClick={onConfirm}>
            <Icon name="trash" />
            Delete
          </button>
        </div>
      </div>
    </div>
  );
}

function ImagePreview() {
  const [dialogOpen, setDialogOpen] = useState(false);
  const [deleted, setDeleted] = useState(false);
  const [toast, setToast] = useState(null);

  const imageName = "Coastal Cliffs at Dawn.jpg";

  const openDialog = useCallback(() => setDialogOpen(true), []);
  const closeDialog = useCallback(() => setDialogOpen(false), []);

  const handleConfirm = () => {
    setDialogOpen(false);
    setDeleted(true);
    setToast("Image deleted from your library");
    setTimeout(() => setToast(null), 2600);
  };

  return (
    <div className="app">
      <header className="topbar">
        <div className="brand">◐ Lumen Library</div>
        <div className="crumbs">Library / Photos / <span>Preview</span></div>
      </header>

      <main className="container">
        <div className="card">
          <div className="image-wrap">
            {!deleted ? (
              <img
                src="https://images.unsplash.com/photo-1505765050516-f72dcac9c60e?auto=format&fit=crop&w=1600&q=80"
                alt={imageName}
                onError={(e) => { e.currentTarget.style.display = 'none'; }}
              />
            ) : (
              <div style={{ color: '#94a3b8', fontSize: 14, padding: 40, textAlign: 'center' }}>
                This image has been deleted.
              </div>
            )}
          </div>
          <div className="meta">
            <div>
              <h1>{imageName}</h1>
              <p>4032 × 3024 · 3.2 MB · Added Mar 18</p>
            </div>
            <div className="actions">
              <button className="btn">
                <Icon name="download" />
                Download
              </button>
              <button
                className="trigger btn btn-danger"
                onClick={openDialog}
                disabled={deleted}
              >
                <Icon name="trash" />
                Delete
              </button>
            </div>
          </div>
        </div>
      </main>

      <ConfirmDeleteDialog
        open={dialogOpen}
        onCancel={closeDialog}
        onConfirm={handleConfirm}
        imageName={imageName}
      />

      {toast && <div className="toast" role="status">{toast}</div>}
    </div>
  );
}

